INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'ROADMAP-1: QNFO.OPS W2-J-CAP-4: per-id revocation of qnfo-tools-mcp capability tokens (a revoked-id list read by capVerify, written by a root-only route)',
 'code-task: repo=qnfo-workers path=qnfo-tools-mcp/worker.js' || char(10) ||
 'code-anchor: async function capVerify(token, env, nowMs) {' || char(10) ||
 'code-probe: {"paths": ["qnfo-tools-mcp/worker.js"], "contains": "capability_revocations"}' || char(10) || char(10) ||
 'Charter pillar security (program QNFO.OPS); roadmap row RM-BS-CAPABILITY-SECURITY-1 (3265), blue-sky B9 / AGT-18; item 4 of the independent review of PR 7661. A capability token is valid until its x caveat (at most 24 hours); nothing can end one earlier, so a token that leaked into a log or a sandbox stays good for hours.' || char(10) ||
 'DO: the table capability_revocations (id TEXT PRIMARY KEY, revoked_at, reason, revoked_by) already exists in qnfo-audit (created by migrations/2026-11-05-w2j-rm-bs-status-1.sql). In capVerify, after the chain verifies, look the token id up (SELECT 1 FROM capability_revocations WHERE id = ?1, a primary-key read through env.AUDIT; qnfo-tools-mcp already binds it) and refuse a revoked id; a read error fails OPEN with a console line and an mcp_log row (tokens expire in 24 hours at most, and a D1 overload must not shut every minted token) - state that choice in the release note. Add POST /mcp/revoke {id, reason} that only the write root (MCP_TOKEN, not a capability token and not MCP_READ_TOKEN) may call, writing one row and one mcp_log line. A revoked id also ends its open SSE sessions at the next POST. Tests in qnfo-tools-mcp/capability-token.test.mjs: revoke then 401 on /mcp, revoke ends a stream, a read-only root cannot revoke, a D1 error fails open. Bump with scripts/worker_release.py --minor.' || char(10) ||
 'Definition of done: merged and verified live: GET /mcp/cap-selftest still ok:true and reports a revocation check; a tokenless POST /mcp/revoke answers 401; recorded in issue_triage.close_evidence.',
 'session:w2-j', 'optimization', 'medium', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'ROADMAP-1: QNFO.OPS W2-J-CAP-4%' AND status = 'open');
